# Let's do a more systematic check - for each class, find features where it's an outlier
for c in range(10):
    row = W['fc.weight'][c]
    for f in range(64):
        val = row[f].item()
        other_vals = [W['fc.weight'][c2, f].item() for c2 in range(10) if c2 != c]
        mean_other = np.mean(other_vals)
        std_other = np.std(other_vals)
        if std_other > 0:
            z = (val - mean_other) / std_other
            if z > 4:
                print(f"Class {c} ({CLASSES[c]}): feature {f} = {val:.4f}, z={z:.2f}, mean_other={mean_other:.4f}")
            elif z < -4:
                print(f"Class {c} ({CLASSES[c]}): feature {f} = {val:.4f}, z={z:.2f}, mean_other={mean_other:.4f} (negative outlier)")

print("\nDone checking outliers.")
